  7→namespace Magento\Framework\Filesystem\Driver;
  8→
  9→use Magento\Framework\Exception\FileSystemException;
 10→
 11→/**
 12→ * Origin filesystem driver. Allows interacting with http endpoint like with FileSystem
 13→ */
 14→class Http extends File
 15→{
 16→    /**
 17→     * Scheme distinguisher
 18→     *
 19→     * @var string
 20→     */
 21→    protected $scheme = 'http';
 22→
 23→    /**
 24→     * Checks if path exists
 25→     *
 26→     * @param string $path
 27→     * @return bool
 28→     */
 29→    public function isExists($path)
 30→    {
 31→        $headers = array_change_key_case(get_headers($this->getScheme() . $path, 1), CASE_LOWER);
 32→        $status = $headers[0] ?? '';
 33→
 34→        /* Handling 301 or 302 redirection */
 35→        if (isset($headers[1]) && preg_match('/30[12]/', $status)) {
 36→            $status = $headers[1];
 37→        }
 38→
 39→        return !(strpos($status, '200') === false);
 40→    }
 41→
 42→    /**
 43→     * Gathers the statistics of the given path
 44→     *
 45→     * @param string $path
 46→     * @return array
 47→     * @SuppressWarnings(PHPMD.NPathComplexity)
 48→     */
 49→    public function stat($path)
 50→    {
 51→        $headers = array_change_key_case(get_headers($this->getScheme() . $path, 1), CASE_LOWER);
 52→
 53→        $result = [
 54→            'dev' => 0,
 55→            'ino' => 0,
 56→            'mode' => 0,
 57→            'nlink' => 0,
 58→            'uid' => 0,
 59→            'gid' => 0,
 60→            'rdev' => 0,
 61→            'atime' => 0,
 62→            'ctime' => 0,
 63→            'blksize' => 0,
 64→            'blocks' => 0,
 65→            'size' => isset($headers['content-length']) ? $headers['content-length'] : 0,
 66→            'type' => isset($headers['content-type']) ? $headers['content-type'] : '',
 67→            'mtime' => isset($headers['last-modified']) ? $headers['last-modified'] : 0,
 68→            'disposition' => isset($headers['content-disposition']) ? $headers['content-disposition'] : null,
 69→        ];
 70→        return $result;
 71→    }
 72→
 73→    /**
 74→     * Retrieve file contents from given path
 75→     *
 76→     * @param string $path
 77→     * @param string|null $flags
 78→     * @param resource|null $context
 79→     * @return string
 80→     * @throws FileSystemException
 81→     */
 82→    public function fileGetContents($path, $flags = null, $context = null)
 83→    {
 84→        $fullPath = $this->getScheme() . $path;
 85→        clearstatcache(false, $fullPath);
 86→        $result = @file_get_contents($fullPath, $flags ?? false, $context);
 87→        if (false === $result) {
 88→            throw new FileSystemException(
 89→                new \Magento\Framework\Phrase(
 90→                    'The contents from the "%1" file can\'t be read. %2',
 91→                    [$path, $this->getWarningMessage()]
 92→                )
 93→            );
 94→        }
 95→        return $result;
 96→    }
 97→
 98→    /**
 99→     * Open file in given path
100→     *
101→     * @param string $path
102→     * @param string $content
103→     * @param string|null $mode
104→     * @param resource|null $context
105→     * @return int The number of bytes that were written
106→     * @throws FileSystemException
107→     */
108→    public function filePutContents($path, $content, $mode = null, $context = null)
109→    {
110→        $result = @file_put_contents($this->getScheme() . $path, $content, $mode, $context);
111→        if ($result === false) {
112→            throw new FileSystemException(
113→                new \Magento\Framework\Phrase(
114→                    'The specified "%1" file couldn\'t be written. %2',
115→                    [$path, $this->getWarningMessage()]
116→                )
117→            );
118→        }
119→        return $result;
120→    }
121→
122→    /**
123→     * Open file
124→     *
125→     * @param string $path
126→     * @param string $mode
127→     * @return resource file
128→     * @throws FileSystemException
129→     * @SuppressWarnings(PHPMD.UnusedFormalParameter)
130→     */
131→    public function fileOpen($path, $mode)
132→    {
133→        $urlProp = $this->parseUrl($this->getScheme() . $path);
134→
135→        if (false === $urlProp) {
136→            throw new FileSystemException(
137→                new \Magento\Framework\Phrase('The download URL is incorrect. Verify and try again.')
138→            );
139→        }
140→
141→        $hostname = $urlProp['host'];
142→        $port = 80;
143→
144→        if (isset($urlProp['port'])) {
145→            $port = (int)$urlProp['port'];
146→        }
147→
148→        $path = '/';
149→        if (isset($urlProp['path'])) {
150→            $path = $urlProp['path'];
151→        }
152→
153→        $query = '';
154→        if (isset($urlProp['query'])) {
155→            $query = '?' . $urlProp['query'];
156→        }
157→
158→        $result = $this->open($hostname, $port);
159→
160→        $headers = 'GET ' .
161→            $path .
162→            $query .
163→            ' HTTP/1.0' .
164→            "\r\n" .
165→            'Host: ' .
166→            $hostname .
167→            "\r\n" .
168→            'User-Agent: Magento' .
169→            "\r\n" .
170→            'Connection: close' .
171→            "\r\n" .
172→            "\r\n";
173→
174→        fwrite($result, $headers);
175→
176→        // trim headers
177→        while (!feof($result)) {
178→            $str = fgets($result, 1024);
179→            if ($str == "\r\n") {
180→                break;
181→            }
182→        }
183→
184→        return $result;
185→    }
186→
187→    /**
188→     * Reads the line content from file pointer (with specified number of bytes from the current position).
189→     *
190→     * @param resource $resource
191→     * @param int $length
192→     * @param string $ending [optional]
193→     * @return string
194→     * @throws FileSystemException
195→     */
196→    public function fileReadLine($resource, $length, $ending = null)
197→    {
198→        try {
199→            $result = @stream_get_line($resource, $length, $ending);
200→        } catch (\Exception $e) {
201→            throw new FileSystemException(
202→                new \Magento\Framework\Phrase('Stream get line failed %1', [$e->getMessage()])
203→            );
204→        }
205→        return $result;
206→    }
207→
208→    /**
209→     * Get absolute path
210→     *
211→     * @param string $basePath
212→     * @param string $path
213→     * @param string|null $scheme
214→     * @return string
215→     * @SuppressWarnings(PHPMD.UnusedFormalParameter)
216→     */
217→    public function getAbsolutePath($basePath, $path, $scheme = null)
218→    {
219→        // check if the path given is already an absolute path containing the
220→        // basepath. so if the basepath starts at position 0 in the path, we
221→        // must not concatinate them again because path is already absolute.
222→        if (0 === strpos((string)$path, (string)$basePath)) {
223→            return $this->getScheme() . $path;
224→        }
225→
226→        return $this->getScheme() . $basePath . $path;
227→    }
228→
229→    /**
230→     * Return path with scheme
231→     *
232→     * @param null|string $scheme
233→     * @return string
234→     */
235→    protected function getScheme($scheme = null)
236→    {
237→        $scheme = $scheme ?: $this->scheme;
238→        return $scheme ? $scheme . '://' : '';
239→    }
240→
241→    /**
242→     * Open a url
243→     *
244→     * @param string $hostname
245→     * @param int $port
246→     * @throws \Magento\Framework\Exception\FileSystemException
247→     * @return resource|bool
248→     */
249→    protected function open($hostname, $port)
250→    {
251→        $result = @fsockopen($hostname, $port, $errorNumber, $errorMessage);
252→        if ($result === false) {
253→            throw new FileSystemException(
254→                new \Magento\Framework\Phrase(
255→                    'Something went wrong while connecting to the host. Error#%1 - %2.',
256→                    [$errorNumber, $errorMessage]
257→                )
258→            );
259→        }
260→        return $result;
261→    }
262→
263→    /**
264→     * Parse a http url
265→     *
266→     * @param string $path
267→     * @return array
268→     */
269→    protected function parseUrl($path)
270→    {
271→        return parse_url($path);
272→    }
273→}
274→

