 8→use Magento\Framework\Filesystem\DriverInterface;
 9→use Magento\Framework\Filesystem\DriverPool;
10→
11→/**
12→ * Opens a file for reading
13→ * @api
14→ * @since 100.0.2
15→ */
16→class ReadFactory
17→{
18→    /**
19→     * Pool of filesystem drivers
20→     *
21→     * @var DriverPool
22→     */
23→    private $driverPool;
24→
25→    /**
26→     * Constructor
27→     *
28→     * @param DriverPool $driverPool
29→     */
30→    public function __construct(DriverPool $driverPool)
31→    {
32→        $this->driverPool = $driverPool;
33→    }
34→
35→    /**
36→     * Create a {@see ReaderInterface}
37→     *
38→     * @param string $path
39→     * @param DriverInterface|string $driver Driver or driver code
40→     * @return \Magento\Framework\Filesystem\File\ReadInterface
41→     */
42→    public function create($path, $driver)
43→    {
44→        if (is_string($driver)) {
45→            return new Read($path, $this->driverPool->getDriver($driver));
46→        }
47→        return new Read($path, $driver);
48→    }
49→}
