  6→namespace Magento\CatalogImportExport\Model\Import;
  7→
  8→use Magento\Framework\App\Filesystem\DirectoryList;
  9→use Magento\Framework\App\ObjectManager;
 10→use Magento\Framework\Exception\FileSystemException;
 11→use Magento\Framework\Exception\LocalizedException;
 12→use Magento\Framework\Exception\ValidatorException;
 13→use Magento\Framework\Filesystem;
 14→use Magento\Framework\Filesystem\Directory\TargetDirectory;
 15→use Magento\Framework\Filesystem\DriverPool;
 16→
 17→/**
 18→ * Import entity product model
 19→ *
 20→ * @api
 21→ * @since 100.0.2
 22→ * @SuppressWarnings(PHPMD.CouplingBetweenObjects)
 23→ * phpcs:disable Magento2.Functions.DiscouragedFunction
 24→ */
 25→class Uploader extends \Magento\MediaStorage\Model\File\Uploader
 26→{
 27→
 28→    /**
 29→     * HTTP scheme
 30→     * used to compare against the filename and select the proper DriverPool adapter
 31→     * @var string
 32→     */
 33→    private $httpScheme = 'http://';
 34→
 35→    /**
 36→     * Temp directory.
 37→     *
 38→     * @var string
 39→     */
 40→    protected $_tmpDir = '';
 41→
 42→    /**
 43→     * Destination directory.
 44→     *
 45→     * @var string
 46→     */
 47→    protected $_destDir = '';
 48→
 49→    /**
 50→     * All mime types.
 51→     *
 52→     * @var array
 53→     */
 54→    protected $_allowedMimeTypes = [
 55→        'jpg' => 'image/jpeg',
 56→        'jpeg' => 'image/jpeg',
 57→        'gif' => 'image/gif',
 58→        'png' => 'image/png',
 59→    ];
 60→
 61→    public const DEFAULT_FILE_TYPE = 'application/octet-stream';
 62→
 63→    /**
 64→     * @var \Magento\Framework\Image\AdapterFactory
 65→     */
 66→    protected $_imageFactory;
 67→
 68→    /**
 69→     * @var \Magento\MediaStorage\Model\File\Validator\NotProtectedExtension
 70→     */
 71→    protected $_validator;
 72→
 73→    /**
 74→     * Instance of filesystem directory write interface.
 75→     *
 76→     * @var \Magento\Framework\Filesystem\Directory\WriteInterface
 77→     */
 78→    protected $_directory;
 79→
 80→    /**
 81→     * Instance of filesystem read factory.
 82→     *
 83→     * @var \Magento\Framework\Filesystem\File\ReadFactory
 84→     */
 85→    protected $_readFactory;
 86→
 87→    /**
 88→     * Instance of media file storage database.
 89→     *
 90→     * @var \Magento\MediaStorage\Helper\File\Storage\Database
 91→     */
 92→    protected $_coreFileStorageDb;
 93→
 94→    /**
 95→     * Instance of media file storage.
 96→     *
 97→     * @var \Magento\MediaStorage\Helper\File\Storage
 98→     */
 99→    protected $_coreFileStorage;
100→
101→    /**
102→     * Instance of random data generator.
103→     *
104→     * @var \Magento\Framework\Math\Random
105→     */
106→    private $random;
107→
108→    /**
109→     * @var Filesystem
110→     */
111→    private $fileSystem;
112→
113→    /**
114→     * Directory and filename must be no more than 255 characters in length
115→     *
116→     * @var int
117→     */
118→    private $maxFilenameLength = 255;
119→
120→    /**
121→     * @var TargetDirectory
122→     */
123→    private $targetDirectory;
124→
125→    /**
126→     * @param \Magento\MediaStorage\Helper\File\Storage\Database $coreFileStorageDb
127→     * @param \Magento\MediaStorage\Helper\File\Storage $coreFileStorage
128→     * @param \Magento\Framework\Image\AdapterFactory $imageFactory
129→     * @param \Magento\MediaStorage\Model\File\Validator\NotProtectedExtension $validator
130→     * @param Filesystem $filesystem
131→     * @param Filesystem\File\ReadFactory $readFactory
132→     * @param string|null $filePath
133→     * @param \Magento\Framework\Math\Random|null $random
134→     * @param TargetDirectory|null $targetDirectory
135→     * @throws FileSystemException
136→     * @throws LocalizedException
137→     */
138→    public function __construct(
139→        \Magento\MediaStorage\Helper\File\Storage\Database $coreFileStorageDb,
140→        \Magento\MediaStorage\Helper\File\Storage $coreFileStorage,
141→        \Magento\Framework\Image\AdapterFactory $imageFactory,
142→        \Magento\MediaStorage\Model\File\Validator\NotProtectedExtension $validator,
143→        Filesystem $filesystem,
144→        Filesystem\File\ReadFactory $readFactory,
145→        $filePath = null,
146→        ?\Magento\Framework\Math\Random $random = null,
147→        ?TargetDirectory $targetDirectory = null
148→    ) {
149→        $this->_imageFactory = $imageFactory;
150→        $this->_coreFileStorageDb = $coreFileStorageDb;
151→        $this->_coreFileStorage = $coreFileStorage;
152→        $this->_validator = $validator;
153→        $this->fileSystem = $filesystem;
154→        $this->_directory = $filesystem->getDirectoryWrite(DirectoryList::ROOT);
155→        $this->_readFactory = $readFactory;
156→        if ($filePath !== null) {
157→            $this->_setUploadFile($filePath);
158→        }
159→        $this->random = $random ?: ObjectManager::getInstance()->get(\Magento\Framework\Math\Random::class);
160→        $this->targetDirectory = $targetDirectory ?: ObjectManager::getInstance()->get(TargetDirectory::class);
161→    }
162→
163→    /**
164→     * Initiate uploader default settings
165→     *
166→     * @return void
167→     */
168→    public function init()
169→    {
170→        $this->setAllowRenameFiles(true);
171→        $this->setAllowCreateFolders(true);
172→        $this->setFilesDispersion(true);
173→        $this->setAllowedExtensions(array_keys($this->_allowedMimeTypes));
174→        $imageAdapter = $this->_imageFactory->create();
175→        $this->addValidateCallback('catalog_product_image', $imageAdapter, 'validateUploadFile');
176→        $this->_uploadType = self::SINGLE_STYLE;
177→    }
178→
179→    /**
180→     * Proceed moving a file from TMP to destination folder
181→     *
182→     * @param string $fileName
183→     * @param bool $renameFileOff
184→     * @return array
185→     * @throws LocalizedException
186→     */
187→    public function move($fileName, $renameFileOff = false)
188→    {
189→        $this->setAllowRenameFiles(!$renameFileOff);
190→
191→        if ($fileName && preg_match('/\bhttps?:\/\//i', $fileName, $matches)) {
192→            $url = str_replace($matches[0], '', $fileName);
193→            $driver = ($matches[0] === $this->httpScheme) ? DriverPool::HTTP : DriverPool::HTTPS;
194→            $tmpFilePath = $this->downloadFileFromUrl($url, $driver);
195→        } else {
196→            $tmpFilePath = $this->_directory->getRelativePath($this->getTempFilePath($fileName));
197→        }
198→
199→        $this->_setUploadFile($tmpFilePath);
200→        $rootDirectory = $this->targetDirectory->getDirectoryRead(DirectoryList::ROOT);
201→        $destDir = $rootDirectory->getAbsolutePath($this->getDestDir());
202→        $result = $this->save($destDir);
203→
204→        if (\is_array($result)) {
205→            unset($result['path']);
206→            $result['name'] = self::getCorrectFileName($result['name']);
207→
208→            // Directory and filename must be no more than 255 characters in length
209→            if (strlen($result['file'] ?? '') > $this->maxFilenameLength) {
210→                throw new \LengthException(
211→                    __('Filename is too long; must be %1 characters or less', $this->maxFilenameLength)
212→                );
213→            }
214→        }
215→
216→        return $result;
217→    }
218→
219→    /**
220→     * Writes a url-based file to the temp directory.
221→     *
222→     * @param string $url
223→     * @param string $driver
224→     * @return string
225→     * @throws LocalizedException
226→     */
227→    private function downloadFileFromUrl($url, $driver)
228→    {
229→        $parsedUrlPath = parse_url($url, PHP_URL_PATH);
230→
231→        if (!$parsedUrlPath) {
232→            throw new LocalizedException(__('Could not parse resource url.'));
233→        }
234→        $urlPathValues = explode('/', $parsedUrlPath);
235→        $fileName = preg_replace('/[^a-z0-9\._-]+/i', '', end($urlPathValues));
236→        //phpcs:ignore Magento2.Functions.DiscouragedFunction
237→        $fileExtension = pathinfo($fileName, PATHINFO_EXTENSION);
238→
239→        if ($fileExtension && !$this->checkAllowedExtension($fileExtension)) {
240→            throw new LocalizedException(__('Disallowed file type.'));
241→        }
242→        $tmpFileName = str_replace(".$fileExtension", '', $fileName);
243→        $tmpFileName .= '_' . $this->random->getRandomString(16);
244→        $tmpFileName .= $fileExtension ? ".$fileExtension" : '';
245→        $tmpFilePath = $this->_directory->getRelativePath($this->getTempFilePath($tmpFileName));
246→
247→        if (!$this->_directory->isWritable($this->getTmpDir())) {
248→            throw new LocalizedException(
249→                __('Import images directory must be writable in order to process remote images.')
250→            );
251→        }
252→        $this->_directory->writeFile(
253→            $tmpFilePath,
254→            $this->_readFactory->create($url, $driver)->readAll()
255→        );
256→
257→        return $tmpFilePath;
258→    }
259→
260→    /**
261→     * Prepare information about the file for moving
262→     *
263→     * @param string $filePath
264→     * @return void
265→     * @throws LocalizedException
266→     */
267→    protected function _setUploadFile($filePath)
268→    {
269→        try {
270→            $fullPath = $this->_directory->getAbsolutePath($filePath);
271→            if ($this->getTmpDir()) {
272→                $tmpDir = $this->fileSystem->getDirectoryReadByPath(
273→                    $this->_directory->getAbsolutePath($this->getTmpDir())
274→                );
275→            } else {
276→                $tmpDir = $this->_directory;
277→            }
278→            $readable = $tmpDir->isReadable($fullPath);
279→        } catch (ValidatorException $exception) {
280→            $readable = false;
281→        }
282→        if (!$readable) {
283→            throw new LocalizedException(
284→                __('File \'%1\' was not found or has read restriction.', $filePath)
285→            );
286→        }
287→        $this->_file = $this->_readFileInfo($filePath);
288→
289→        $this->_validateFile();
290→    }
291→
292→    /**
293→     * Reads file info
294→     *
295→     * @param string $filePath
296→     * @return array
297→     */
298→    protected function _readFileInfo($filePath)
299→    {
300→        $fullFilePath = $this->_directory->getAbsolutePath($filePath);
301→        $fileInfo = pathinfo($fullFilePath);
302→        return [
303→            'name' => $fileInfo['basename'],
304→            'type' => $this->_getMimeTypeByExt($fileInfo['extension']),
305→            'tmp_name' => $filePath,
306→            'error' => 0,
307→            'size' => $this->_directory->stat($filePath)['size']
308→        ];
309→    }
310→
311→    /**
312→     * Validate uploaded file by type and etc.
313→     *
314→     * @return void
315→     * @throws LocalizedException
316→     */
317→    protected function _validateFile()
318→    {
319→        $filePath = $this->_file['tmp_name'];
320→        if ($this->_directory->isReadable($filePath)) {
321→            $this->_fileExists = true;
322→        } else {
323→            $this->_fileExists = false;
324→        }
325→
326→        $fileExtension = pathinfo($filePath, PATHINFO_EXTENSION);
327→        if (!$this->checkAllowedExtension($fileExtension)) {
328→            throw new LocalizedException(__('Disallowed file type.'));
329→        }
