113→    /**
114→     * @param \Magento\Framework\App\Helper\Context $context
115→     * @param File $downloadableFile
116→     * @param \Magento\MediaStorage\Helper\File\Storage\Database $coreFileStorageDb
117→     * @param Filesystem $filesystem
118→     * @param \Magento\Framework\Session\SessionManagerInterface $session
119→     * @param Filesystem\File\ReadFactory $fileReadFactory
120→     * @param Mime|null $mime
121→     */
122→    public function __construct(
123→        \Magento\Framework\App\Helper\Context $context,
124→        \Magento\Downloadable\Helper\File $downloadableFile,
125→        \Magento\MediaStorage\Helper\File\Storage\Database $coreFileStorageDb,
126→        \Magento\Framework\Filesystem $filesystem,
127→        \Magento\Framework\Session\SessionManagerInterface $session,
128→        \Magento\Framework\Filesystem\File\ReadFactory $fileReadFactory,
129→        ?Mime $mime = null
130→    ) {
131→        parent::__construct($context);
132→        $this->_downloadableFile = $downloadableFile;
133→        $this->_coreFileStorageDb = $coreFileStorageDb;
134→        $this->_filesystem = $filesystem;
135→        $this->_session = $session;
136→        $this->fileReadFactory = $fileReadFactory;
137→        $this->mime = $mime ?? ObjectManager::getInstance()->get(Mime::class);
138→    }
139→
140→    /**
141→     * Retrieve Resource file handle (socket, file pointer etc)
142→     *
143→     * @return \Magento\Framework\Filesystem\File\ReadInterface
144→     * @throws CoreException|\Exception
145→     */
146→    protected function _getHandle()
147→    {
148→        if (!$this->_resourceFile) {
149→            throw new CoreException(__('Please set resource file and link type.'));
150→        }
151→
152→        if ($this->_handle === null) {
153→            if ($this->_linkType == self::LINK_TYPE_URL) {
154→                $path = $this->_resourceFile;
155→                // phpcs:ignore Magento2.Functions.DiscouragedFunction
156→                $protocol = strtolower(parse_url($path, PHP_URL_SCHEME));
157→                if ($protocol) {
158→                    // Strip down protocol from path
159→                    $path = preg_replace('#.+://#', '', $path);
160→                }
161→                $this->_handle = $this->fileReadFactory->create($path, $protocol);
162→            } elseif ($this->_linkType == self::LINK_TYPE_FILE) {
163→                $this->_workingDirectory = $this->_filesystem->getDirectoryRead(DirectoryList::MEDIA);
164→                $fileExists = $this->_downloadableFile->ensureFileInFilesystem($this->_resourceFile);
165→                if ($fileExists) {
166→                    $this->_handle = $this->_workingDirectory->openFile($this->_resourceFile);
167→                } else {
168→                    throw new CoreException(__('Invalid download link type.'));
169→                }
170→            } else {
171→                throw new CoreException(__('Invalid download link type.'));
172→            }
173→        }
174→        return $this->_handle;
175→    }
176→
177→    /**
178→     * Retrieve file size in bytes
179→     *
180→     * @return int
181→     */
182→    public function getFileSize()
183→    {
184→        return $this->_getHandle()->stat($this->_resourceFile)['size'];
185→    }
186→
187→    /**
188→     * Return MIME type of a file.
189→     *
190→     * @return string
191→     */
192→    public function getContentType()
193→    {
194→        $this->_getHandle();
195→        if ($this->_linkType === self::LINK_TYPE_FILE) {
196→            $absolutePath = $this->_workingDirectory->getAbsolutePath($this->_resourceFile);
197→            return $this->mime->getMimeType($absolutePath);
198→        }
199→        if ($this->_linkType === self::LINK_TYPE_URL) {
200→            return (is_array($this->_handle->stat($this->_resourceFile)['type'])
201→                ? end($this->_handle->stat($this->_resourceFile)['type'])
202→                : $this->_handle->stat($this->_resourceFile)['type']);
203→        }
204→        return $this->_contentType;
205→    }
206→
207→    /**
208→     * Return name of the file
209→     *
210→     * @return string
211→     * phpcs:disable Magento2.Functions.DiscouragedFunction
212→     * phpcs:disable Generic.PHP.NoSilencedErrors
213→     */
214→    public function getFilename()
215→    {
216→        $this->_getHandle();
217→        if ($this->_linkType == self::LINK_TYPE_FILE) {
218→            return pathinfo($this->_resourceFile, PATHINFO_BASENAME);
219→        } elseif ($this->_linkType == self::LINK_TYPE_URL) {
220→            $stat = $this->_handle->stat($this->_resourceFile);
221→            if (isset($stat['disposition'])) {
222→                $contentDisposition = explode('; ', $stat['disposition']);
223→                if (!empty($contentDisposition[1]) && preg_match(
224→                    '/filename=([^ ]+)/',
225→                    $contentDisposition[1],
226→                    $matches
227→                )
228→                ) {
229→                    return $matches[1];
230→                }
231→            }
232→            $fileName = @pathinfo($this->_resourceFile, PATHINFO_BASENAME);
233→            if ($fileName) {
234→                return $fileName;
235→            }
236→        }
237→        return $this->_fileName;
238→    }
239→
240→    /**
241→     * Set resource file for download
242→     *
243→     * @param string $resourceFile
244→     * @param string $linkType
245→     * @return $this
246→     * @throws \InvalidArgumentException
247→     */
248→    public function setResource($resourceFile, $linkType = self::LINK_TYPE_FILE)
249→    {
250→        if (self::LINK_TYPE_FILE == $linkType) {
251→            //check LFI protection
252→            if ($resourceFile && preg_match('#\.\.[\\\/]#', $resourceFile)) {
253→                throw new \InvalidArgumentException(
254→                    'Requested file may not include parent directory traversal ("../", "..\\" notation)'
255→                );
256→            }
257→        }
258→
259→        $this->_resourceFile = $resourceFile;
260→
261→        /**
262→        * check header for urls
263→        */
264→        if ($linkType === self::LINK_TYPE_URL) {
265→            // phpcs:ignore Magento2.Functions.DiscouragedFunction
266→            $headers = array_change_key_case(get_headers($this->_resourceFile, 1), CASE_LOWER);
267→            if (isset($headers['location'])) {
268→                $this->_resourceFile  = is_array($headers['location']) ? current($headers['location'])
269→                    : $headers['location'];
270→            }
271→        }
272→
273→        $this->_linkType = $linkType;
274→        return $this;
275→    }
276→
