 * @return bool|string
 */
public function read($filename, $dest = null)
{
    $result = false;

    $this->_cwd();
    $filename = (string)$filename;
    if ($dest === null) {
        $result = @file_get_contents($filename);
    } elseif (is_resource($dest)) {
        $result = @file_get_contents($filename);
        fwrite($dest, $result);
    } elseif (is_string($dest)) {
        $result = @copy($filename, $dest);
    }
    $this->_iwd();

    return $result;
}

